import 'dart:async';import 'package:flutter/foundation.dart';import '../domain/models/contact.dart';import '../data/contact_service.dart';import '../data/contact_group_service.dart';class ContactsBloc {  final ContactService _contactService;  final ContactGroupService _groupService;  final _stateController = StreamController<ContactsState>.broadcast();  ContactsBloc(this._contactService, this._groupService);  Stream<ContactsState> get state => _stateController.stream;  ContactsState _currentState = ContactsInitial();  Future<void> loadContacts() async {    _emit(ContactsLoading());    try {      final contacts = _contactService.getAll();      final groups = _groupService.getAll();      _emit(ContactsLoaded(contacts: contacts, groups: groups));    } catch (e) {      _emit(ContactsError(e.toString()));    }  }  Future<void> addContact(Contact contact) async {    await _contactService.saveContact(contact);    await loadContacts();  }  Future<void> deleteContact(String deviceId) async {    await _contactService.deleteContact(deviceId);    await loadContacts();  }  Future<void> toggleTrusted(String deviceId) async {    final contact = _contactService.getContact(deviceId);    if (contact != null) {      await _contactService.setTrusted(deviceId, !contact.isTrusted);      await loadContacts();    }  }  Future<void> blockContact(String deviceId) async {    final contact = _contactService.getContact(deviceId);    if (contact != null) {      final updated = contact.copyWith(isBlocked: true);      await _contactService.saveContact(updated);      await loadContacts();    }  }  Future<void> updateContact(Contact contact) async {    await _contactService.saveContact(contact);    await loadContacts();  }  Future<void> createGroup(String name, {int? color}) async {    await _groupService.createGroup(name, colorValue: color);    await loadContacts();  }  Future<void> deleteGroup(ContactGroupModel group) async {    await _groupService.deleteGroup(group);    await loadContacts();  }  Future<void> addToGroup(String groupName, String contactId) async {    await _groupService.addContactToGroup(groupName, contactId);    await loadContacts();  }  Future<void> removeFromGroup(String groupName, String contactId) async {    await _groupService.removeContactFromGroup(groupName, contactId);    await loadContacts();  }  void _emit(ContactsState state) {    _currentState = state;    _stateController.add(state);  }  ContactsState get currentState => _currentState;  void dispose() {    _stateController.close();  }}abstract class ContactsState {}class ContactsInitial extends ContactsState {}class ContactsLoading extends ContactsState {}class ContactsLoaded extends ContactsState {  final List<Contact> contacts;  final List<ContactGroupModel> groups;  ContactsLoaded({required this.contacts, required this.groups});}class ContactsError extends ContactsState {  final String message;  ContactsError(this.message);}